insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25522')::uuid, md5('building-colonnaden-39-20354')::uuid, '25522', 'neustadt-bueroflaeche-in-den-colonnaden-25522', 'Neustadt: Bürofläche in den Colonnaden', 'Das Bürogebäude befindet sich in exponierter Innenstadtlage in den Colonnaden. Der in wenigen Gehminuten erreichte Dammtorbahnhof, die U-Bahnstation Stephansplatz sowie diverse …', 'Das Bürogebäude befindet sich in exponierter Innenstadtlage in den Colonnaden. Der in wenigen Gehminuten erreichte Dammtorbahnhof, die U-Bahnstation Stephansplatz sowie diverse Buslinien gewährleisten eine hervorragende Anbindung an den ÖPNV. Zahlreiche Cafés und Restaurants sowie vielfältige Einkaufsmöglichkeiten unterstreichen die Attraktivität dieser begehrten Innenstadtlage. Die vakante Gewerbefläche befindet sich aktuell im Altzustand und wird in Absprache mit dem neuen Mieter ausgebaut und ausgestattet. PKW-Stellplätze sind bei Bedarf im Umfeld anzumieten.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', false, 3, 'Dieses Mietangebot ist courtagepflichtig für den Mieter.*', '{}'::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_25522.pdf', null, 'filemaker', '25522') on conflict (id) do nothing;
