insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-16228')::uuid, md5('building-eiffestrasse-68-20537')::uuid, '16228', 'preiswerte-bueroflaeche-in-der-city-sued-16228', 'Preiswerte Bürofläche in der City-Süd', 'Das West India Haus befindet sich in gut sichtbarer Lage an der Eiffestraße. Die Anbindung an den ÖPNV ist durch die nahe gelegenen U- und S-Bahnhaltestellen Burgstraße und …', 'Das West India Haus befindet sich in gut sichtbarer Lage an der Eiffestraße. Die Anbindung an den ÖPNV ist durch die nahe gelegenen U- und S-Bahnhaltestellen Burgstraße und Berliner Tor gesichert. Auch die Autobahnanschlüsse zur A1 und A24 sind schnell erreicht. Diverse Restaurants befinden sich in direkter Umgebung. Die frisch renovierte Bürofläche im 3. OG wird über ein Foyer mit Personenaufzug erschlossen und teilt sich in drei Räume. Zur Ausstattung zählen Teppichfußboden, Beleuchtungssysteme, eine Verkabelung in Fensterbrüstungskanälen, Türen mit Glasausschnitten und ein Pantryanschluss. Getrennte WC-Einheiten befinden sich auf dem Flur und werden gemeinschaftlich mit einem Nachbarn genutzt. Ein PKW-Stellplatz kann angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_16228.pdf', null, 'filemaker', '16228') on conflict (id) do nothing;
