insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-13650')::uuid, md5('building-alter-wall-34-36-20457')::uuid, '13650', 'altstadt-charmantes-buero-direkt-am-rathaus-13650', 'Altstadt: Charmantes Büro direkt am Rathaus', 'Das markante Büro- und Geschäftsgebäude befindet sich in bester Lage der Hamburger Innenstadt, in unmittelbarer Nähe zur Handelskammer, dem Rathausmarkt und der Binnenalster. Das …', 'Das markante Büro- und Geschäftsgebäude befindet sich in bester Lage der Hamburger Innenstadt, in unmittelbarer Nähe zur Handelskammer, dem Rathausmarkt und der Binnenalster. Das attraktive Umfeld ist durch hochwertige Einzelhändler, alle Geschäfte des täglichen Bedarfs sowie eine Vielzahl gastronomischer Angebote geprägt. Der Anschluss an das öffentliche Verkehrsnetz kann durch die nahe gelegene U- und S-Bahnstation Jungfernstieg als hervorragend bezeichnet werden. insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-13650-1')::uuid, md5('property-13650')::uuid, 'Mietfläche', 120, 28, null, 'filemaker', '13650-1') on conflict (id) do nothing;
