insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-22479')::uuid, md5('building-grosse-bleichen-21-20354')::uuid, '22479', 'attraktive-einzelhandelsflaeche-in-bester-innenstadtlage-22479', 'Attraktive Einzelhandelsfläche in bester Innenstadtlage', 'Die Galleria ist eine der bekanntesten Hamburger Einkaufspassagen und befindet sich in bester Innenstadtlage in unmittelbarer Nähe zum Bleichenfleet und zum Hanseviertel. Das …', 'Die Galleria ist eine der bekanntesten Hamburger Einkaufspassagen und befindet sich in bester Innenstadtlage in unmittelbarer Nähe zum Bleichenfleet und zum Hanseviertel. Das elegante Büro- und Geschäftsgebäude zählt zu Hamburgs Topadressen. Die hier angebotene, zweigeschossige Ladenfläche mitten in der Passage mit großen Schaufenstern erstreckt sich über ca. 66 qm im EG und ca. 56 qm im 1.OG. Die WC-Fläche befindet sich außerhalb der Mietfläche. Archivflächen und Pkw-Stellplätze sind im Untergeschoss vorhanden.', 'laden-gastro', array['laden-gastro']::property_category[], 'laden', 'published', 'qm', 'zzgl. NK u. MwSt.', false, 3.6, 'Dieses Mietangebot ist courtagepflichtig für den Mieter.*', '{}'::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_22479.pdf', null, 'filemaker', '22479') on conflict (id) do nothing;
