insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25299')::uuid, md5('building-zippelhaus-5a-20457')::uuid, '25299', 'bueroflaeche-in-zentraler-hafenlage-25299', 'Bürofläche in zentraler Hafenlage', 'Das Bürogebäude liegt sehr zentral gegenüber der historischen Speicherstadt in ruhiger Hoflage. Das Umfeld ist geprägt durch zahlreiche kleine Cafés und Restaurants. Die …', 'Das Bürogebäude liegt sehr zentral gegenüber der historischen Speicherstadt in ruhiger Hoflage. Das Umfeld ist geprägt durch zahlreiche kleine Cafés und Restaurants. Die Mönckebergstraße, mit allen Geschäften des täglichen Bedarfs, als auch die U-Bahnstation Meßberg sind nach wenigen Gehminuten erreicht. Das Gebäude verfügt über einen repräsentativen Eingangsbereich sowie einen Personenaufzug. insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-25299-1')::uuid, md5('property-25299')::uuid, 'Mietfläche', 125, 21.5, null, 'filemaker', '25299-1') on conflict (id) do nothing;
