insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-13455')::uuid, md5('building-kleine-johannisstrasse-9-20457')::uuid, '13455', 'perfekte-aufteilung-bueroflaeche-in-rathausnaehe-zum-sofortigen-bezug-13455', 'Perfekte Aufteilung: Bürofläche in Rathausnähe zum sofortigen Bezug', 'Das repräsentative Büro- und Geschäftshaus befindet sich in bester Citylage nahe dem Rathausmarkt, der Mönckebergstraße und der Binnenalster. Das Umfeld ist geprägt durch alle …', 'Das repräsentative Büro- und Geschäftshaus befindet sich in bester Citylage nahe dem Rathausmarkt, der Mönckebergstraße und der Binnenalster. Das Umfeld ist geprägt durch alle Geschäfte des täglichen Bedarfs sowie eine Vielzahl an Cafés und Restaurants. Die U- und S-Bahnstationen Rathausmarkt und Jungfernstieg sorgen für eine sehr gute Anbindung an das öffentliche Verkehrsnetz. Die moderne Bürofläche wird über ein historisches Foyer mit Personenaufzug erschlossen. Zur Ausstattung zählen Amticofußboden in Holzoptik, Teppichfußboden, Beleuchtungssysteme, eine CAT-7-Verkabelung in Bodenkabelkanälen, ein Serverraum, Glastüren, Glaselemente in den Trennwänden, hohe Decken, alte Säulen, getrennte WC-Einheiten, eine Dusche im Herren-WC und eine neue Pantry mit Geschirrspüler und Kühl-Gefrierkombi. Das Büro wird komplett möbliert und inklusive hochwertiger Küchengeräte vermietet. In der Nebenkostenpauschale sind bereits die Kosten für die wöchentliche Reinigung, zwei separate Internetanschlüsse (Telekom DSL, Vodafone Kabel) sowie Strom enthalten.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', false, 3, 'Dieses Mietangebot ist courtagepflichtig für den Mieter.*', '{}'::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_13455.pdf', null, 'filemaker', '13455') on conflict (id) do nothing;
