insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-22485')::uuid, md5('building-osakaallee-1-2-20457')::uuid, '22485', 'keine-gastronomie-ausgebaute-ladenflaeche-im-ueberseeboulevard-22485', 'Keine Gastronomie: Ausgebaute Ladenfläche im Überseeboulevard', 'Die kompakte Ladenfläche überzeugt mit lichter Raumhöhe und befindet sich direkt am Überseeboulevard in der stetig wachsenden HafenCity. Sie ist mit zwei Eingängen sowohl vom …', 'Die kompakte Ladenfläche überzeugt mit lichter Raumhöhe und befindet sich direkt am Überseeboulevard in der stetig wachsenden HafenCity. Sie ist mit zwei Eingängen sowohl vom Boulevard als auch von der Osakaallee aus zu begehen. Vielseitige Einkaufsmöglichkeiten, diverse Restaurants, Cafés, Clubs, Boutiquen Galerien und diverse Dienstleister beleben bereits jetzt diese aufstrebende Lage, welche mit diversen Buslinien und der nahe gelegenen U-Bahn-Station gut an das öffentliche Verkehrsnetz angeschlossen ist. Die Ausstattung der Fläche umfasst eine kleine Galerie, eine Küchenzeile und eine WC-Einheit. PKW-Stellplätze stehen in der Tiefgarage zur Anmietung bereit.', 'laden-gastro', array['laden-gastro']::property_category[], 'laden', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['erdgeschoss']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_22485.pdf', null, 'filemaker', '22485') on conflict (id) do nothing;
