insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-18086')::uuid, md5('building-neuer-wall-36-38-20354')::uuid, '18086', 'moderne-praxisflaeche-am-neuen-wall-18086', 'Moderne Praxisfläche am Neuen Wall', 'Das Büro- und Geschäftsgebäude befindet sich unmittelbar am Bleichenfleet, nur wenige Meter von der Binnenalster und dem Rathausmarkt entfernt. Die U- und S-Bahnstation …', 'Das Büro- und Geschäftsgebäude befindet sich unmittelbar am Bleichenfleet, nur wenige Meter von der Binnenalster und dem Rathausmarkt entfernt. Die U- und S-Bahnstation Jungfernstieg ist in wenigen Gehminuten erreicht. Das direkte Umfeld dieser exponierten Innenstadtlage ist geprägt durch elegante Boutiquen, bekannte Designer-Label, hochwertigen Einzelhandel und zahlreiche Cafés und Restaurants. Das Gebäude verfügt über einen repräsentativen Eingangsbereich sowie einen Personenaufzug. Die aktuelle Ausstattung umfasst einen Hohlraumboden für die EDV-Verkabelung, außenliegenden Sonnenschutz und separate WC-Einheiten. Die Aufteilung erfolgt in Absprache mit dem zukünftigen Mieter. Pkw-Stellplätze können im Umfeld angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', '{}'::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_18086.pdf', null, 'filemaker', '18086') on conflict (id) do nothing;
