insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-8610')::uuid, md5('building-grosse-elbstrasse-145a-f-22767')::uuid, '8610', 'penthousebuero-mit-balkon-und-einmaligem-elbblick-8610', 'Penthousebüro mit Balkon und einmaligem Elbblick', 'Das Elbkaihaus befindet sich in bester Elblage mit direktem Hafenblick. Der Bahnhof Altona mit zahlreichen Einkaufsmöglichkeiten und Geschäften des täglichen Bedarfs ist in …', 'Das Elbkaihaus befindet sich in bester Elblage mit direktem Hafenblick. Der Bahnhof Altona mit zahlreichen Einkaufsmöglichkeiten und Geschäften des täglichen Bedarfs ist in wenigen Fahrminuten erreicht. Die transparent gestaltete Mietfläche ist u.a. mit Birkenholzparkett, einem außenliegenden Sonnenschutz sowie individuell einstellbaren Trennwänden als Stahl o. Glaskonstruktion ausgestattet. Zudem verfügt die Mietfläche über ein Bodenkabelkanalsystem, ein Design-Leuchtsystem, eine Gegensprechanlage, eine Sprinkleranlage sowie eine Teeküche und sanitäre Anlagen. Ein zur Elbseite gelegener Balkon gehört ebenfalls zur Mietfläche.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-8610-1')::uuid, md5('property-8610')::uuid, 'Mietfläche', 133, 25, null, 'filemaker', '8610-1') on conflict (id) do nothing;
