insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-19925')::uuid, md5('building-kleine-reichenstrasse-11-20457')::uuid, '19925', 'hochwertige-bueroflaeche-nahe-des-domplatzes-19925', 'Hochwertige Bürofläche nahe des Domplatzes', 'Das moderne Büro- und Geschäftsgebäude befindet sich in ruhiger Lage in unmittelbarer Nähe zum Domplatz. Viele gastronomische Angebote, die U-Bahnstationen Messberg und Rathaus …', 'Das moderne Büro- und Geschäftsgebäude befindet sich in ruhiger Lage in unmittelbarer Nähe zum Domplatz. Viele gastronomische Angebote, die U-Bahnstationen Messberg und Rathaus sowie die Hamburger Speicherstadt befinden sich im direkten Umfeld und sind fußläufig schnell erreicht. Die helle Bürofläche ist sehr hochwertig ausgestattet. Hierzu zählen u. a. Glastrennwände, eine schöne Pantry, eine bereits verlegte EDV-Verkabelung, bodentiefe Fensterelemente, Deckenfluter sowie getrennte WC-Einheiten. PKW-Stellplätze können bei Bedarf direkt am Objekt angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_19925.pdf', null, 'filemaker', '19925') on conflict (id) do nothing;
