insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-19558')::uuid, md5('building-frankenstrasse-3-7-20097')::uuid, '19558', 'moderne-bueroflaeche-in-verkehrsguenstiger-lage-19558', 'Moderne Bürofläche in verkehrsgünstiger Lage', 'Das Bürogebäude befindet sich in einer ruhigen und verkehrsgünstigen Lage, unweit der S-Bahnstation Hammerbrook. Eine schnelle Anbindung an die City sowie die …', 'Das Bürogebäude befindet sich in einer ruhigen und verkehrsgünstigen Lage, unweit der S-Bahnstation Hammerbrook. Eine schnelle Anbindung an die City sowie die Autobahnanschlussstelle ist gegeben. Eine vielseitige Auswahl gastronomischer Betriebe sowie Geschäfte für kleinere Einkäufe sind fußläufig schnell erreicht. Die Bürofläche  wird in Absprache mit dem zukünftigen Mieter neu aufgeteilt und ausgestattet. Die Ausstattung bei einem 5 Jahresmietvertrag umfasst u.a. Teppichfußboden in den Büros und Designbelag im Flur, weiß gestrichene Wände, neue Türgriffe und Steckdosenabdeckungen. PKW-Stellplätze können nach Absprache angemietet werden. Die Innenansichten stammen aus einem Musterbüro im Objekt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 150, 680, 'https://www.buerohamburg.de/objects/pdf/BHI_19558.pdf', null, 'filemaker', '19558') on conflict (id) do nothing;
