insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-23990')::uuid, md5('building-grosse-elbstrasse-117-131-22767')::uuid, '23990', 'bueroflaeche-mit-blick-auf-elbe-und-hafen-23990', 'Bürofläche mit Blick auf Elbe und Hafen', 'Direkt am Hafenbecken im belebten Stadtteil Altona-Altstadt, befindet sich diese Gewerbefläche. Die Anbindung an den ÖPNV ist durch die nahegelegene S-Bahnstation Königstraße, die …', 'Direkt am Hafenbecken im belebten Stadtteil Altona-Altstadt, befindet sich diese Gewerbefläche. Die Anbindung an den ÖPNV ist durch die nahegelegene S-Bahnstation Königstraße, die Buslinie 111 sowie die Hadag-Fähre gewährleistet. Das direkte Umfeld ist geprägt von renommierten Nachbarn wie dem Stilwerk und zahlreichen namenhaften Gastronomen. Zusätzlich siedeln sich in der Großen Elbstraße immer mehr hochwertige Delikatessen- und Einzelhändler an, wie das Frischeparadies oder Rindchen, ein bekannter Weinhändler. Die Fläche verfügt über Fußbodenbelag, eine Pantry sowie WC-Einheiten. Diese Innenbilder sind beispielhaft gewählt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', '{}'::text[], 136, 161, 'https://www.buerohamburg.de/objects/pdf/BHI_23990.pdf', null, 'filemaker', '23990') on conflict (id) do nothing;
