insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-17385')::uuid, md5('building-steinhoeft-11-20459')::uuid, '17385', 'kompakte-endetage-zwischen-hafen-und-innenstadt-17385', 'Kompakte Endetage zwischen Hafen und Innenstadt', 'Das Slomanhaus befindet sich in markanter Ecklage direkt am Hamburger Hafen. Die nahe gelegenen U-Bahn-Stationen Baumwall und Meßberg sichern eine sehr gute Anbindung an den …', 'Das Slomanhaus befindet sich in markanter Ecklage direkt am Hamburger Hafen. Die nahe gelegenen U-Bahn-Stationen Baumwall und Meßberg sichern eine sehr gute Anbindung an den öffentlichen Nahverkehr. Auch die Autobahnen A1 und A7 sind schnell erreicht. Im direkten Umfeld befinden sich diverse Cafés und Restaurants für abwechslungsreiche Mittagspausen. Die Innenstadt mit allen Einkaufsmöglichkeiten ist fußläufig gut erreichbar. Die historische Außenfassade und die großzügigen Treppenhäuser des denkmalgeschützten Gebäudes wurden in der Vergangenheit umfangreich restauriert. Die vakante Einheit befindet sich im obersten Stockwerk und besticht durch ihre effiziente Aufteilung. Zur Ausstattung zählen u. a. teilweise Glasausschnitte und getrennte WC -Einheiten innerhalb der Mietfläche. Die weitere Ausstattung erfolgt in Absprache mit dem zukünftigen Mieter. PKW-Stellplätze können im Umfeld angemietet werden. Diese Innenbilder sind beispielhaft gewählt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', '{}'::text[], 137, 956, 'https://www.buerohamburg.de/objects/pdf/BHI_17385.pdf', null, 'filemaker', '17385') on conflict (id) do nothing;
