insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-19949')::uuid, md5('building-am-neumarkt-30-22041')::uuid, '19949', 'klassische-bueroflaeche-im-skandinavien-center-19949', 'Klassische Bürofläche im Skandinavien-Center', 'Der Gewerbekomplex liegt in kurzer Entfernung zum Wandsbeker Zentrum mit seinen U- und S-Bahn Linien sowie den Autobahnen A1 und A24. Die hellen Büroflächen sind sowohl über einen …', 'Der Gewerbekomplex liegt in kurzer Entfernung zum Wandsbeker Zentrum mit seinen U- und S-Bahn Linien sowie den Autobahnen A1 und A24. Die hellen Büroflächen sind sowohl über einen Personen- als auch Lastenaufzug zu erreichen und können in Absprache mit dem zukünftigen Mieter aufgeteilt und ausgestattet werden. Hierzu wir u.a. zählen: Teppichbodenbelag, Standardbeleuchtung, WC-Bereiche sowie eine Pantry. Archiv- und Lagerflächen können ebenso angemietet werden wie PKW-Stellplätze im Außenbereich. Die Innenansichten stammen aus einer ähnlichen Fläche im Gebäude.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['lastenaufzug', 'erdgeschoss', 'stellplaetze']::text[], 138, 299, 'https://www.buerohamburg.de/objects/pdf/BHI_19949.pdf', null, 'filemaker', '19949') on conflict (id) do nothing;
