insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-6184')::uuid, md5('building-borsteler-bogen-27-22453')::uuid, '6184', 'moderne-loftflaeche-in-alter-schokoladenfabrik-6184', 'Moderne Loftfläche in alter Schokoladenfabrik', 'Die ehemalige Schokoladenfabrik befindet sich umgeben von Bäumen in ruhiger Hoflage zwischen Eppendorf und dem Flughafen und ermöglicht so dem Nutzer ein kreatives Arbeiten mitten …', 'Die ehemalige Schokoladenfabrik befindet sich umgeben von Bäumen in ruhiger Hoflage zwischen Eppendorf und dem Flughafen und ermöglicht so dem Nutzer ein kreatives Arbeiten mitten im Grünen. Der Anschluss an den ÖPNV ist durch eine nahegelegene Bushaltestelle gegeben. Zahlreiche Restaurants und Geschäfte des täglichen Bedarfs sind fußläufig schnell erreicht. Zur Ausstattung der lichtdurchfluteten Bürofläche gehört u.a ein Industrie-Estrichboden mit Verkabelungsmöglichkeiten, Designleuchten und sehr hochwertig ausgestattete WC-Einheiten.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-6184-1')::uuid, md5('property-6184')::uuid, 'Mietfläche', 139, 19, null, 'filemaker', '6184-1') on conflict (id) do nothing;
