insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24531')::uuid, md5('building-virchowstrasse-17-19-22767')::uuid, '24531', 'moderne-flaeche-zur-untervermietung-in-altona-24531', 'Moderne Fläche zur Untervermietung in Altona', 'In zentraler Lage zwischen dem Bahnhof Altona und der S-Bahn-Station Königstraße befindet sich dieses gepflegte Büro- und Geschäftsgebäude inmitten eines urbanen, lebendigen …', 'In zentraler Lage zwischen dem Bahnhof Altona und der S-Bahn-Station Königstraße befindet sich dieses gepflegte Büro- und Geschäftsgebäude inmitten eines urbanen, lebendigen Umfelds. Die direkte Umgebung bietet zahlreiche Einkaufsmöglichkeiten sowie charmante Cafés und Restaurants – ideal für die Mittagspause oder geschäftliche Treffen. Zur Untermiete stehen vier Büroräume mit einer Größe von je ca. 25 qm, welche Teil einer modernen und bereits vermieteten Büroeinheit sind. Die Flächen bieten eine ruhige, konzentrierte Arbeitsatmosphäre. Zusätzlich steht den Mietern eine großzügige, voll ausgestattete Küche sowie ein stilvoll eingerichteter Aufenthaltsbereich zur gemeinschaftlichen Nutzung zur Verfügung. Die anteilige Fläche dieser Gemeinschaftsbereiche beträgt ca. 40 qm und ist bereits in der Gesamtmietfläche enthalten. Sie schaffen Raum für kreative Pausen, kurze Meetings oder einen informellen Austausch im Alltag. Der angegebene Pauschalmietpreis umfasst sämtliche Nebenkosten – darunter Strom, Wasser sowie die regelmäßige Reinigung der gemeinschaftlich genutzten Flächen. Die Anmietung erfolgt provisionsfrei und bietet eine unkomplizierte Möglichkeit, einen inspirierenden Arbeitsplatz in attraktiver Lage zu beziehen. Bei Bedarf kann – je nach Verfügbarkeit – ein weiterer Büroraum mit ca. 25 qm zusätzlich angemietet werden, was diese Lösung besonders interessant für wachsende Teams oder flexible Nutzungskonzepte macht.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'monat', 'inkl. NK, zzgl. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter.', '{}'::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_24531.pdf', null, 'filemaker', '24531') on conflict (id) do nothing;
