insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25318')::uuid, md5('building-kedenburgstrasse-44-22041')::uuid, '25318', 'helle-bueroflaeche-in-historischer-fabrik-25318', 'Helle Bürofläche in historischer Fabrik', 'Das historische Fabrikgelände befindet sich in ruhiger Wandsbeker Lage nahe dem Eichtalpark. Der Verkehrsknotenpunkt Horner Kreisel mit Anschluss an die A1 und die A24 ist in …', 'Das historische Fabrikgelände befindet sich in ruhiger Wandsbeker Lage nahe dem Eichtalpark. Der Verkehrsknotenpunkt Horner Kreisel mit Anschluss an die A1 und die A24 ist in wenigen Fahrminuten erreicht. Der nahe gelegene U-, S- und Busbahnhof Wandsbek Markt sichert die Anbindung an das öffentliche Verkehrsnetz. Zahlreiche Restaurants, Cafés und Geschäfte des täglichen Bedarfs befinden sich im Einkaufszentrum Quarree am Wandsbek Markt. Die helle Bürofläche erschließt sich über ein großzügiges Treppenhaus. Zur aktuellen Ausstattung zählen eine Verkabelung, Beleuchtungssysteme, separate gemeinschaftliche WC-Einheiten und eine Teeküche. PKW-Stellplätze können im Umfeld angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_25318.pdf', null, 'filemaker', '25318') on conflict (id) do nothing;
