insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-8909')::uuid, md5('building-eiffestrasse-68-20537')::uuid, '8909', 'gut-angebundene-bueroflaeche-mit-kompaktem-grundriss-8909', 'Gut angebundene Bürofläche mit kompaktem Grundriss', 'In verkehrsgünstiger Ecklage, direkt an der Eiffestraße, liegt das Bürogebäude „West India Haus“. Eine Anbindung an den ÖPNV ist durch die nahe gelegenen U-Bahnstationen …', 'In verkehrsgünstiger Ecklage, direkt an der Eiffestraße, liegt das Bürogebäude „West India Haus“. Eine Anbindung an den ÖPNV ist durch die nahe gelegenen U-Bahnstationen Burgstraße und Berliner Tor gegeben. Auch die Autobahnanschlüsse sind schnell erreicht. Diverse Restaurants befinden sich in direkter Umgebung. Die hier angebotene Bürofläche ist bereits ausgebaut und verfügt über Teppichfußboden, eine CAT-5-Verkabelung in Fensterbrüstungskanälen, Beleuchtungssysteme sowie eine Pantry. Getrennte WC-Einheiten sind vorhanden und werden gemeinschaftlich mit anderen Mieters der Etage genutzt. Die Fläche wird über einen Fahrstuhl erschlossen. PKW-Stellplätze können angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_8909.pdf', null, 'filemaker', '8909') on conflict (id) do nothing;
