insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-18981')::uuid, md5('building-am-sandtorkai-38-41-20457')::uuid, '18981', 'ab-sofort-kompaktes-buero-im-columbus-haus-mit-terrasse-18981', 'Ab sofort: kompaktes Büro im Columbus Haus mit Terrasse', 'Das Columbus Haus bildet das Tor zur HafenCity. Der markante Turm besticht durch seine beeindruckende Glaskonstruktion und die außergewöhnliche Architektur. Die Hamburger City ist …', 'Das Columbus Haus bildet das Tor zur HafenCity. Der markante Turm besticht durch seine beeindruckende Glaskonstruktion und die außergewöhnliche Architektur. Die Hamburger City ist in wenigen Gehminuten erreicht. Die Anbindung an den ÖPNV ist durch die U-Bahn-Stationen Baumwall und Rödingsmarkt gesichert. Im Umfeld befinden sich zahlreiche Cafés und Restaurants. Die helle und sehr hochwertig ausgestattete Bürofläche kann den individuellen Bedürfnissen des zukünftigen Mieters angepasst werden. Zur aktuellen Ausstattung zählen Teppichfußboden, Beleuchtungssysteme, Bodentanks, getrennte WC-Bereiche und eine Pantry. Highlight ist eine ca. 50 qm große Terrasse, welche mit ca. 25 qm zur oben genannten Mietfläche addiert wird. PKW-Stellplätze stehen zur Anmietung in der Tiefgarage bereit. Diese Innenbilder sind beispielhaft gewählt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['balkon-terrasse', 'stellplaetze', 'wasserblick']::text[], 142, 1156, 'https://www.buerohamburg.de/objects/pdf/BHI_18981.pdf', null, 'filemaker', '18981') on conflict (id) do nothing;
