insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25253')::uuid, md5('building-cremon-11-20457')::uuid, '25253', 'bueroflaeche-mit-balkon-zwischen-rathaus-und-speicherstadt-25253', 'Bürofläche mit Balkon zwischen Rathaus und Speicherstadt', 'Das klassische Geschäftshaus mit markanter Außenfassade befindet sich in zentraler Lage zwischen Hafencity und Neustadt, nahe den U-Bahnstationen Rödingsmarkt und Baumwall. Eine …', 'Das klassische Geschäftshaus mit markanter Außenfassade befindet sich in zentraler Lage zwischen Hafencity und Neustadt, nahe den U-Bahnstationen Rödingsmarkt und Baumwall. Eine Vielzahl an gastronomischen Einrichtungen, Einkaufsmöglichkeiten und Geschäften des täglichen Bedarfs sind fußläufig schnell erreicht. insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-25253-1')::uuid, md5('property-25253')::uuid, 'Mietfläche', 142, 20, null, 'filemaker', '25253-1') on conflict (id) do nothing;
