insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-14947')::uuid, md5('building-suederstrasse-282-20537')::uuid, '14947', 'hanseatische-atmosphaere-im-stoertebeker-haus-14947', 'Hanseatische Atmosphäre im Störtebeker Haus', 'Das Büro- und Geschäftshaus befindet sich in zentraler City-Süd-Lage an den Hauptverkehrsachsen Heidenkampsweg und Amsinckstraße. Die Autobahnen 1, 7 und 24 sind in wenigen …', 'Das Büro- und Geschäftshaus befindet sich in zentraler City-Süd-Lage an den Hauptverkehrsachsen Heidenkampsweg und Amsinckstraße. Die Autobahnen 1, 7 und 24 sind in wenigen Minuten mit dem Pkw erreicht. Das 7- geschossige Störtebeker Haus nimmt mit der besonderen Fassadengestaltung bewusst Bezug zu den traditionellen, hanseatischen Kontorhäusern. Die Büroflächen ist bezugsfertig ausgebaut. Der Ausbaustandard entspricht modernsten Anforderungen. Der Mietpreis variiert je nach Ausstattungswunsch ab 13,90 Euro pro qm. PKW-Stellplätze können nach Absprache am Gebäude zusätzlich angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['barrierefrei', 'stellplaetze']::text[], 160, 682, 'https://www.buerohamburg.de/objects/pdf/BHI_14947.pdf', null, 'filemaker', '14947') on conflict (id) do nothing;
