insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25574')::uuid, md5('building-beim-alten-gaswerk-1-22761')::uuid, '25574', 'moderne-bueroflaeche-im-ehemaligen-gaswerk-in-bahrenfeld-25574', 'Moderne Bürofläche im ehemaligen Gaswerk in Bahrenfeld', 'Das moderne Bürogebäude befindet sich im urbanen Bahrenfeld auf einem der größten, denkmalgeschützten Areale Europas. Die nahegelegene S-Bahn-Station Bahrenfeld und die …', 'Das moderne Bürogebäude befindet sich im urbanen Bahrenfeld auf einem der größten, denkmalgeschützten Areale Europas. Die nahegelegene S-Bahn-Station Bahrenfeld und die Bushaltestelle Celsiusweg sichern eine gute Anbindung an den öffentlichen Personenverkehr. Gute Einkaufsmöglichkeiten und ein vielseitiges gastronomisches Angebot unterstreichen die Attraktivität dieser gut angebundenen Lage. Die helle Mietfläche erschließt sich über ein großzügiges Foyer mit Personenaufzug und verfügt u.a. über bodentiefe Fenster, Vinyl-Fußboden, innenliegenden Sonnenschutz und eine Küchenzeile. Die weitere Ausstattung und Aufteilung erfolgt in Absprache mit dem zukünftigen Mieter. Diese Innenbilder sind beispielhaft gewählt und stammen aus einer ähnlichen Fläche im Objekt. Ein PKW- Stellplatz kann zusätzlich angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', false, 3, 'Dieses Mietangebot ist courtagepflichtig für den Mieter.*', array['stellplaetze']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_25574.pdf', null, 'filemaker', '25574') on conflict (id) do nothing;
