insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25467')::uuid, md5('building-winterhuder-weg-29-31-22085')::uuid, '25467', 'funktionale-bueroflaeche-am-winterhuder-weg-25467', 'Funktionale Bürofläche am Winterhuder Weg', 'Das markante Bürogebäude befindet sich in lebendiger Lage auf der Grenze zwischen Winterhude und Barmbek-Süd. Das Umfeld ist geprägt durch zahlreiche Geschäfte des täglichen …', 'Das markante Bürogebäude befindet sich in lebendiger Lage auf der Grenze zwischen Winterhude und Barmbek-Süd. Das Umfeld ist geprägt durch zahlreiche Geschäfte des täglichen Bedarfs sowie eine Vielzahl an Cafés und Restaurants. Auch das EKZ Hamburger Meile liegt nur wenige Fußminuten entfernt. Direkt vor dem Objekt befindet sich eine Bushaltestelle und die U-Bahnstation Mundburg liegt nur wenige 100 Meter entfernt. Die helle Bürofläche wird über ein großzügiges Foyer mit zwei Personenaufzügen erschlossen. Die Bürofläche kann nach den individuellen Wünschen des Mieters ausgestattet und gestaltet werden. Die Bilder sind beispielhaft gewählt.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-25467-1')::uuid, md5('property-25467')::uuid, 'Mietfläche', 170, 15, null, 'filemaker', '25467-1') on conflict (id) do nothing;
