insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-13016')::uuid, md5('building-hoheluftchaussee-21-20253')::uuid, '13016', 'moderne-bueroflaeche-mit-dachterrasse-im-herzen-von-hoheluft-13016', 'Moderne Bürofläche mit Dachterrasse im Herzen von Hoheluft', 'Der markante Neubau befindet sich in lebendiger Stadtteillage Hoheluft am Isebekkanal. Die U-Bahnstation Hoheluftbrücke sowie diverse Bushaltestellen sind fußläufig schnell …', 'Der markante Neubau befindet sich in lebendiger Stadtteillage Hoheluft am Isebekkanal. Die U-Bahnstation Hoheluftbrücke sowie diverse Bushaltestellen sind fußläufig schnell erreicht. Vielseitige Einkaufsmöglichkeiten und zahlreiche Cafés und Restaurants prägen das lebendige Umfeld. Die aktuelle Ausstattung der barrierefreien Bürofläche umfasst aktuell hochwertigen Amitco- und Teppichbodenbelag, teilweise Glastrennwände, eine CAT-7 Verkabelung in Bodentanks, eine vollausgestattete Pantry sowie separate WC-Einheiten. Ein besonderes Highlight ist die großzügige, zum Hinterhof ausgerichtete ca. 73 qm große Dachterrasse, welche direkt aus der Mietung zu begehen ist und die hälftig der Mietfläche hinzugerechnet wird. Die Anmietung eines Tiefgaragenstellplatzes ist möglich.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['balkon-terrasse', 'barrierefrei', 'stellplaetze']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_13016.pdf', null, 'filemaker', '13016') on conflict (id) do nothing;
