insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-16312')::uuid, md5('building-stresemannstrasse-342-22761')::uuid, '16312', 'moderne-bueroflaeche-in-markanter-ecklage-in-bahrenfeld-16312', 'Moderne Bürofläche in markanter Ecklage in Bahrenfeld', 'Das imposante Büro- und Geschäftsgebäude befindet sich in markanter Ecklage im Stadtteil Bahrenfeld. Gute Einkaufsmöglichkeiten und diverse Cafés und Restaurants sind fußläufig …', 'Das imposante Büro- und Geschäftsgebäude befindet sich in markanter Ecklage im Stadtteil Bahrenfeld. Gute Einkaufsmöglichkeiten und diverse Cafés und Restaurants sind fußläufig schnell erreicht. Der S-Bahnhof Diebsteich und verschiedene Buslinien sichern eine gute Anbindung an das öffentliche Verkehrsnetz. Die moderne Bürofläche wird über ein repräsentatives Foyer mit Personenaufzug erschlossen. Zur aktuellen Ausstattung zählen Amtico- und Teppichfußboden, Beleuchtungssysteme, Fensterbrüstungskanälen, innen liegender Sonnenschutz, ein Serverraum, getrennte WC-Einheiten und eine Pantry. PKW-Stellplätze können in der hauseigenen Tiefgarage angemietet werden. Die Innenansichten stammen aus einer renovierten Fläche im Gebäude.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['barrierefrei', 'stellplaetze']::text[], 173, 196, 'https://www.buerohamburg.de/objects/pdf/BHI_16312.pdf', null, 'filemaker', '16312') on conflict (id) do nothing;
