insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-19178')::uuid, md5('building-borsteler-bogen-27-22453')::uuid, '19178', 'loftflaeche-mit-balkon-im-revitalisierten-schokoloft-19178', 'Loftfläche mit Balkon im revitalisierten Schokoloft', 'Die ehemalige Schokoladenfabrik befindet sich umgeben von Bäumen in ruhiger Hoflage zwischen Eppendorf und dem Flughafen und ermöglicht so dem Nutzer ein kreatives Arbeiten mitten …', 'Die ehemalige Schokoladenfabrik befindet sich umgeben von Bäumen in ruhiger Hoflage zwischen Eppendorf und dem Flughafen und ermöglicht so dem Nutzer ein kreatives Arbeiten mitten im Grünen. Der Anschluss an den ÖPNV ist durch eine nahegelegene Bushaltestelle gegeben. Zahlreiche Restaurants und Geschäfte des täglichen Bedarfs sind fußläufig schnell zu erreichen. Zur Ausstattung der lichtdurchfluteten Büro- Loftfläche gehört u.a ein Industrie-Estrichboden mit Verkabelungsmöglichkeiten, Designleuchten und hochwertig ausgestattete WC-Einheiten. PKW-Stellplätze können nach Anfrage auf dem Gelände angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', false, 3, 'Dieses Mietangebot ist courtagepflichtig für den Mieter.*', array['balkon-terrasse', 'lastenaufzug']::text[], 114, 349, 'https://www.buerohamburg.de/objects/pdf/BHI_19178.pdf', null, 'filemaker', '19178') on conflict (id) do nothing;
