insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-4887')::uuid, md5('building-wendenstrasse-4-6-20097')::uuid, '4887', 'flexibel-gestaltbare-flaechen-in-der-city-sued-4887', 'Flexibel gestaltbare Flächen in der City-Süd', 'Zwischen Heidenkampsweg und Amsinckstraße, unweit der S-Bahnstation Hammerbrook befindet sich dieses Bürogebäude. Das Gebäude verfügt über Personen- sowie Lastenaufzüge, ein …', 'Zwischen Heidenkampsweg und Amsinckstraße, unweit der S-Bahnstation Hammerbrook befindet sich dieses Bürogebäude. Das Gebäude verfügt über Personen- sowie Lastenaufzüge, ein direkter Zugang mit dem Lastenaufzug zur Fläche ist möglich. Zur Ausstattung der Bürofläche zählt unter anderem Teppichbodenbelag, Rastereinbauleuchten, abgehängte Decken, außen liegender Sonnenschutz, sowie eine kleine Teeküche. Die Aufteilung kann nach den individuellen Wünschen des neuen Mieters erfolgen. insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-4887-1')::uuid, md5('property-4887')::uuid, 'Mietfläche', 181, 10, null, 'filemaker', '4887-1') on conflict (id) do nothing;
