insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-22231')::uuid, md5('building-an-der-alster-3-5-20099')::uuid, '22231', 'arbeiten-mit-einzigartigem-alsterblick-22231', 'Arbeiten mit einzigartigem Alsterblick', 'Der von den Architekten Bothe, Richter und Teherani entwickelte, außergewöhnliche Bürokomplex befindet sich In exponierter Lage direkt an der Hamburger Außenalster in St. Georg. …', 'Der von den Architekten Bothe, Richter und Teherani entwickelte, außergewöhnliche Bürokomplex befindet sich In exponierter Lage direkt an der Hamburger Außenalster in St. Georg. Diverse Buslinien und der fußläufig schnell erreichte Hauptbahnhof sichern eine gute Anbindung an das öffentliche Verkehrsnetz. Die Lange Reihe mit vielseitigen Einkaufsmöglichkeiten und zahlreichen Cafés und Restaurants ist direkt nebenan und erhöht die Attraktivität dieser beliebten Stadtteillage. Die effizient aufgeteilte Bürofläche befindet sich im 4. Obergeschoss und erschließt sich über ein modernes Treppenhaus mit zwei Personenaufzügen. Die aktuelle Ausstattung umfasst unter anderem einen Teppichboden, außenliegenden, elektrischen Sonnenschutz, Stehleuchten, Bodentanks, eine Pantry und separate WC-Einheiten. Darüber hinaus steht dem Mieter eine zur Außenalster ausgerichtete Terrasse mit ca. 30 qm zur exklusiven Nutzung zur Verfügung, welche hälftig zur genannten Flächengröße addiert wird.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-22231-1')::uuid, md5('property-22231')::uuid, 'Mietfläche', 183, 30, null, 'filemaker', '22231-1') on conflict (id) do nothing;
